\begin{align*}
f(x) &= x^{-1} + \frac{x^{-1}}{1+x^{-1}} \\
&= \frac{1}{x} + \frac{1}{x(1+\frac{1}{x})} \\
&= \frac{1}{x} + \frac{1}{x+\frac{1}{x}} \\
&= \frac{1}{x} + \frac{1}{x+\frac{1}{x}} \\
&= \frac{1}{x} + \frac{x}{x^2+1} \\
&= \frac{x^2+1+x^2}{x(x^2+1)} \\
&= \frac{2x^2+1}{x(x^2+1)}
\end{align*}
Now, we need to find $f(f(-2))$. We first find $f(-2)$:
\begin{align*}
f(-2) &= \frac{2(-2)^2+1}{(-2)((-2)^2+1)} \\
&= \frac{8+1}{(-2)(4+1)} \\
&= \frac{9}{-2 \cdot 5} \\
&= \frac{-9}{10}
\end{align*}
Next, we find $f(f(-2))$:
\begin{align*}
f(f(-2)) &= f\left(\frac{-9}{10}\right) \\
&= \frac{2\left(\frac{-9}{10}\right)^2+1}{\left(\frac{-9}{10}\right)\left(\left(\frac{-9}{10}\right)^2+1\right)} \\
&= \frac{2\left(\frac{81}{100}\right)+1}{\left(\frac{-9}{10}\right)\left(\frac{81}{100}+1\right)} \\
&= \frac{\frac{162}{100}+\frac{100}{100}}{\left(\frac{-9}{10}\right)\left(\frac{81+100}{100}\right)} \\
&= \frac{\frac{262}{100}}{\left(\frac{-9}{10}\right)\left(\frac{181}{100}\right)} \\
&= \frac{262}{100} \cdot \frac{100}{-9 \cdot 181} \\
&= \frac{262}{-1629} \\
&= \boxed{-\frac{262}{1629}}
\end{align*}

Therefore, the answer is $\boxed{-\frac{262}{1629}}$.

